import{_ as e,c as s,o as t,a}from"./app.19f3f8f0.js";const m=JSON.parse('{"title":"Episode 6 — Why official Instagram tools matter","description":"Business and Creator accounts, permissions, and why ReplyBridge uses Instagram’s supported paths.","frontmatter":{"title":"Episode 6 — Why official Instagram tools matter","description":"Business and Creator accounts, permissions, and why ReplyBridge uses Instagram’s supported paths."},"headers":[{"level":2,"title":"What you’ll do in the app","slug":"what-you-ll-do-in-the-app","link":"#what-you-ll-do-in-the-app","children":[]},{"level":2,"title":"Series complete — what now?","slug":"series-complete-—-what-now","link":"#series-complete-—-what-now","children":[]},{"level":2,"title":"Series","slug":"series","link":"#series","children":[]}],"relativePath":"replybridge/series/06-official-path.md"}'),r={name:"replybridge/series/06-official-path.md"},o=a('<h1 id="episode-6-—-why-official-instagram-tools-matter" tabindex="-1">Episode 6 — Why “official” Instagram tools matter <a class="header-anchor" href="#episode-6-—-why-official-instagram-tools-matter" aria-hidden="true">#</a></h1><p>ReplyBridge is built for <strong>Instagram Business and Creator</strong> accounts and uses <strong>supported</strong> ways to read comments and send messages—so you’re not relying on shady “gray area” bots that can put your account at risk.</p><hr><h2 id="what-you-ll-do-in-the-app" tabindex="-1">What you’ll do in the app <a class="header-anchor" href="#what-you-ll-do-in-the-app" aria-hidden="true">#</a></h2><ul><li><strong>Connect</strong> Instagram through the normal login and permission screens.</li><li><strong>No developer console</strong> and no copying secret keys—you’re a business owner, not an engineer.</li></ul><p>If connection fails, it’s usually fixable: update the Instagram app, confirm your <strong>Business/Creator</strong> setup, and try <strong>Connect</strong> again. More help: <strong><a href="/replybridge/integration">Connect Instagram</a></strong></p><hr><h2 id="series-complete-—-what-now" tabindex="-1">Series complete — what now? <a class="header-anchor" href="#series-complete-—-what-now" aria-hidden="true">#</a></h2><ul><li><strong>Install &amp; full setup:</strong> <a href="/replybridge/getting-started">Get started</a></li><li><strong>Day-to-day tips:</strong> <a href="/replybridge/usage">How to use</a></li><li><strong>Grow your own IG content:</strong> <a href="/replybridge/marketing/">Marketing &amp; tips</a></li></ul><hr><h2 id="series" tabindex="-1">Series <a class="header-anchor" href="#series" aria-hidden="true">#</a></h2><ul><li><strong>Previous:</strong> <a href="/replybridge/series/05-sales-and-events">Episode 5</a></li><li><strong>All episodes:</strong> <a href="/replybridge/series/">Instagram mini-series</a></li></ul>',12),i=[o];function n(l,d,h,p,c,g){return t(),s("div",null,i)}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
